sketch:
tabulate⁻ : ∀ {n} {f : Fin n → A} → Any P (tabulate f) → ∃ λ i → P (f i)
-- Base case: n = 0. Fin 0 has no elements, so tabulate f is the empty list. Any P [] has no proof, so the implication holds vacuously.
tabulate⁻ {zero} {f} p = {!!}
-- Inductive case: n = k + 1. Rewrite tabulate f with tabulateSuc to get Any P (f zero ∷ tabulate (f ∘ suc)).
-- Sub-case: the proof certifies P (f zero). Take the witness i = zero, so P (f zero) is the given proof.
tabulate⁻ {suc k} {f} (here px) = {!!}
-- Sub-case: the proof is Any P (tabulate (f ∘ suc)). Apply the induction hypothesis tabulate⁻ to f ∘ suc to get j : Fin k with P ((f ∘ suc) j). Take the witness suc j, since (f ∘ suc) j = f (suc j) by definition of composition.
tabulate⁻ {suc k} {f} (there pxs) = {!!}

lemmas.tabulateSuc:
{A.a : Level} {A = A₁ : Set A.a} {k : Data.Nat.Base.ℕ}
(f₁ : Fin (suc k) → A₁) →
tabulate f₁ ≡ f₁ zero ∷ tabulate (f₁ ∘ suc)

sketch:
tabulate⁻ : ∀ {n} {f : Fin n → A} → Any P (tabulate f) → ∃ λ i → P (f i)
-- Base case: n = 0. Fin 0 has no elements, so tabulate f is the empty list. Any P [] has no proof, so the implication holds vacuously.
tabulate⁻ {n = zero} {f = f} p = {!!}
-- Inductive case: n = k + 1. Assume the statement holds for k and every function Fin k → A. By tabulateSuc, the proof is a proof of Any P (f zero :: tabulate (f ∘ suc)).
-- Sub-case: the proof certifies P (f zero). Take the witness zero, so P (f zero) is exactly the given proof.
tabulate⁻ {n = suc k} {f = f} (here px) = {!!}
-- Sub-case: the proof is a proof of Any P (tabulate (f ∘ suc)). Apply the induction hypothesis tabulate⁻ to f ∘ suc to get j : Fin k with P ((f ∘ suc) j). Take the witness suc j, since (f ∘ suc) j = f (suc j) by definition of composition.
tabulate⁻ {n = suc k} {f = f} (there pxs) = {!!}

